// A TypeScript port of backend/services/chunking.py and the offline
// HashingEmbedder, so the demo's retrieval behaves like the real thing.
// rag.test.ts checks it against output generated by the Python original.

const MAX_CHARS = 800;
const OVERLAP = 100;
export const DIM = 384;
export const MIN_SCORE = 0.05; // HashingEmbedder.default_min_score
const STOP = new Set(
  'a an and are as at be by for from has have in is it its of on or that the this to was were will with'.split(' '),
);

export function chunkText(text: string, maxChars = MAX_CHARS, overlap = OVERLAP): string[] {
  const paragraphs = text
    .replace(/\r\n/g, '\n')
    .split(/\n\s*\n/)
    .map((p) => p.replace(/[ \t]+/g, ' ').trim());
  const pieceLimit = overlap <= 0 ? maxChars : Math.max(maxChars - overlap - 1, Math.floor(maxChars / 2));
  const pieces: string[] = [];
  for (const paragraph of paragraphs.filter(Boolean)) {
    if (paragraph.length <= maxChars) pieces.push(paragraph);
    else pieces.push(...splitLong(paragraph, pieceLimit));
  }

  const chunks: string[] = [];
  let current = '';
  for (const piece of pieces) {
    if (!current) {
      current = piece;
    } else if (current.length + 2 + piece.length <= maxChars) {
      current += '\n\n' + piece;
    } else {
      chunks.push(current);
      const room = maxChars - piece.length - 1;
      const tail = room >= 20 ? tailOf(current, Math.min(overlap, room)) : '';
      current = tail ? `${tail} ${piece}` : piece;
    }
  }
  if (current) chunks.push(current);
  return chunks;
}

function splitLong(paragraph: string, maxChars: number): string[] {
  const out: string[] = [];
  let current = '';
  for (let sentence of paragraph.split(/(?<=[.!?])\s+/)) {
    while (sentence.length > maxChars) {
      let cut = sentence.lastIndexOf(' ', maxChars - 1);
      if (cut <= 0) cut = maxChars;
      if (current) {
        out.push(current);
        current = '';
      }
      out.push(sentence.slice(0, cut));
      sentence = sentence.slice(cut).trimStart();
    }
    if (!sentence) continue;
    if (!current) current = sentence;
    else if (current.length + 1 + sentence.length <= maxChars) current += ' ' + sentence;
    else {
      out.push(current);
      current = sentence;
    }
  }
  if (current) out.push(current);
  return out;
}

function tailOf(text: string, size: number): string {
  if (size <= 0) return '';
  const tail = text.slice(-size);
  const space = tail.indexOf(' ');
  return space !== -1 && text.length > size ? tail.slice(space + 1) : tail;
}

let crcTable: Uint32Array | undefined;
function crc32(input: string): number {
  if (!crcTable) {
    crcTable = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crcTable[n] = c >>> 0;
    }
  }
  let crc = 0xffffffff;
  for (const byte of new TextEncoder().encode(input)) crc = crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

/** Unit-length bag-of-words vector. Matches shared words, not meaning. */
export function hashEmbed(text: string): Float32Array {
  const vec = new Float32Array(DIM);
  for (const word of text.toLowerCase().match(/[a-z0-9]+/g) ?? []) {
    if (STOP.has(word)) continue;
    const h = crc32(word);
    vec[h % DIM] += (h >>> 16) & 1 ? 1 : -1;
  }
  let norm = 0;
  for (const v of vec) norm += v * v;
  norm = Math.sqrt(norm);
  if (norm > 0) for (let i = 0; i < DIM; i++) vec[i] /= norm;
  return vec;
}

export function dot(a: Float32Array, b: Float32Array): number {
  let sum = 0;
  for (let i = 0; i < a.length; i++) sum += a[i] * b[i];
  return sum;
}
